import { readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const dir = fileURLToPath(new URL("../src/components/ui/", import.meta.url));
const names = readdirSync(dir)
  .filter((f) => f.endsWith(".tsx"))
  .map((f) => f.slice(0, -4))
  .sort();

const lines = [
  "// Generated by `npm run gen:barrel`. The design-system entry point.",
  "",
  'import "@/design-system.css";',
  "",
  ...names.map((n) => `export * from "./${n}";`),
];
writeFileSync(new URL("../src/components/ui/index.ts", import.meta.url), lines.join("\n") + "\n");
console.log(`barrel: ${names.length} modules`);
